ruleToc.chapterList:
@js:
(function(){
  var d = JSON.parse(result);
  var arr = d.chapters || [];
  var out = [];
  var seen = {};
  for (var i=0;i<arr.length;i++){
    var it = arr[i] || {};
    var id = String(it.id || '');
    if (!id || seen[id]) continue;
    seen[id] = 1;
    out.push({
      name: it.title || '',
      url: id
    });
  }
  return out;
})()
